    <div class=\"sectionIII-zwII-text-section\">
         <h1 class=\"sectionIII-zwII-main-heading\">
                    Explore Our <span class=\"sectionIII-zwII-blue-text\">Latest Collections</span> For You
                </h1>

        <p class=\"sectionIII-zwII-description-text\">Discover the newest trends and fresh designs-our latest collection brings you bold prints, timeless styles, and exclusive pieces made to stand out. Find a look that’s uniquely yours</p>
    </div>
    <div class=\"sectionIII-zwII-collections-grid\">
        <!-- Left Column: 1 large card on top, 2 small cards in a row below -->
        <div class=\"sectionIII-zwII-left-column\">
            <!-- Large card 1 (top) -->
            <div class=\"sectionIII-zwII-card sectionIII-zwII-card-large\" style=\"background-image: url('https://zwitchoriginals.com//storage/theme/24/T7RwQSuvXLVAojGNi3tfLL9QsdNvanQdkZBQiqvH.webp');\">
                <div class=\"sectionIII-zwII-card-icon\"></div>
                <div class=\"sectionIII-zwII-card-arrow\"></div>
                <div class=\"sectionIII-zwII-card-overlay\">
                     <h2 class=\"sectionIII-zwII-card-title\">Collection For Couples</h2>

                    <p class=\"sectionIII-zwII-card-description\">Our Collection for Couple Features coordinated designs and patterns, allowing couples to showcase their unity through fashion.</p>
                </div>
            </div>
            <!-- Bottom row: 2 small cards side by side -->
            <div class=\"sectionIII-zwII-bottom-row\">
                <!-- Small card 2 (bottom-left) -->
                <div class=\"sectionIII-zwII-card sectionIII-zwII-card-small\" style=\"background-image: url('https://zwitchoriginals.com//storage/theme/24/849vspnzjVM8GSk0UGfJG7Ub33s7X1rMjKq7jm1s.webp');\">
                    <div class=\"sectionIII-zwII-card-icon\"></div>
                    <div class=\"sectionIII-zwII-card-overlay\">
                         <h2 class=\"sectionIII-zwII-card-title\">Collection For<br>Couples</h2>

                    </div>
                </div>
                <!-- Small card 3 (bottom-right) -->
                <div class=\"sectionIII-zwII-card sectionIII-zwII-card-small\" style=\"background-image: url('https://zwitchoriginals.com//storage/theme/24/g76krO0h2AhSpoaczZ6KqcR4X4gWoZAa7EkvvUYq.webp');\">
                    <div class=\"sectionIII-zwII-card-icon\"></div>
                    <div class=\"sectionIII-zwII-card-overlay\">
                         <h2 class=\"sectionIII-zwII-card-title\">Collection For<br>Couples</h2>

                    </div>
                </div>
            </div>
        </div>
        <!-- Right Column: 1 large card -->
        <div class=\"sectionIII-zwII-right-column\">
            <div class=\"sectionIII-zwII-card sectionIII-zwII-card-large\" style=\"background-image: url('https://zwitchoriginals.com//storage/theme/24/o3sEfqUITFjmAQjMXZQP9LUGhmGCMazLUHoHGIsO.webp');\">
                <div class=\"sectionIII-zwII-card-icon\"></div>
                <div class=\"sectionIII-zwII-card-arrow\"></div>
                <div class=\"sectionIII-zwII-card-overlay\">
                     <h2 class=\"sectionIII-zwII-card-title\">Collection For Couples</h2>

